using System;
using System.Linq;
using System.Collections.Generic;
namespace Ara {
 public static class BlockTools {
  public static bool Same(CellBlock a,CellBlock b){return a.Category==b.Category&&a.Name==b.Name&&a.Score==b.Score&&a.Satisfaction==b.Satisfaction&&a.TemplateId==b.TemplateId&&a.PrepFor==b.PrepFor&&(a.MealId==b.MealId||string.IsNullOrEmpty(a.MealId)||string.IsNullOrEmpty(b.MealId));}
  public static void Merge(List<CellBlock> list){var ordered=list.OrderBy(x=>x.Start).ToList();list.Clear();foreach(var b in ordered){var last=list.LastOrDefault();if(last!=null&&last.End==b.Start&&Same(last,b)&&last.Category!="기상"){last.Count+=b.Count;if(string.IsNullOrEmpty(last.MealId))last.MealId=b.MealId;}else list.Add(b);}}
  public static CellSelection Clamp(List<CellBlock> list,CellBlock source,int lane,string edge,int index,DateTime origin){var prep=lane==0&&!string.IsNullOrEmpty(source.MealId)?list.Find(x=>x.PrepFor==source.MealId):null;int first=(int)((source.Start-origin).TotalMinutes/10),last=first+source.Count-1;int min=prep==null?0:prep.Count,max=287;foreach(var other in list.Where(x=>x!=source&&x!=prep)){if(other.End<=source.Start)min=Math.Max(min,(int)((other.End-origin).TotalMinutes/10)+(prep==null?0:prep.Count));if(other.Start>=source.End)max=Math.Min(max,(int)((other.Start-origin).TotalMinutes/10)-1);}return new CellSelection{Lane=lane,First=edge=="start"?Math.Max(min,Math.Min(last,index)):first,Last=edge=="end"?Math.Max(first,Math.Min(max,index)):last};}
  public static void Resize(List<CellBlock> list,string id,DateTime start,int count,DateTime origin,bool planned){var source=list.Find(x=>x.Id==id);if(source==null)throw new InvalidOperationException("길이를 바꿀 블록이 없습니다.");if(source.Category=="기상")throw new InvalidOperationException("기상 칸은 한 칸으로 유지합니다. 가운데를 끌어 이동해 주세요.");DateTime end=start.AddMinutes(count*10);if(count<1||start<origin.Date||end>origin.Date.AddDays(2)||start.Minute%10!=0||start.Second!=0)throw new InvalidOperationException("10분 이상, 표시 범위 안으로 조절해 주세요.");var prep=planned&&!string.IsNullOrEmpty(source.MealId)?list.Find(x=>x.PrepFor==source.MealId):null;DateTime prepStart=prep==null?start:start.AddMinutes(-prep.Count*10);if(prepStart<origin.Date||list.Any(x=>x!=source&&x!=prep&&GridEngine.Overlap(x,prepStart,end)))throw new InvalidOperationException("다른 블록이 있어 더 늘릴 수 없습니다.");source.Start=start;source.Count=count;source.Minimum=Math.Min(source.Minimum,count);if(prep!=null)prep.Start=prepStart;Merge(list);}
 }
}
